import React, { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';

import App from './App';
import './style.css'; // 👉 Menghubungkan custom CSS

const rootElement = document.getElementById('root');
const root = createRoot(rootElement);

root.render(
  <StrictMode>
    <App />
  </StrictMode>
);
